import{_ as t,o as e,c as a,a8 as i}from"./chunks/framework.BppdKxCY.js";const g=JSON.parse('{"title":"EP.31 排序大比武","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.31-ds-sorting.md","filePath":"comics/EP.31-ds-sorting.md","lastUpdated":1793421673000}'),s={name:"comics/EP.31-ds-sorting.md"};function r(d,o,l,n,c,h){return e(),a("div",null,[...o[0]||(o[0]=[i('<h1 id="ep-31-排序大比武" tabindex="-1">EP.31 排序大比武 <a class="header-anchor" href="#ep-31-排序大比武" aria-label="Permalink to &quot;EP.31 排序大比武&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../22-frontend-data-structures">22-frontend-data-structures.md</a>（22.8 排序算法的比武大会）· 示例：<code>data-structures/examples/22-09-sorting.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：像素酱做表格排序，<code>[10, 9, 1].sort()</code> 竟得到 <code>[1, 10, 9]</code>，分数列当场翻车。</li><li><strong>第 2 格</strong>：码叔揭秘——<code>sort()</code> 默认按字符串字典序；<code>O(n²)</code> 三兄弟（冒泡/选择/插入）对阵 <code>O(n log n)</code> 三剑客（归并/快排/堆排）。</li><li><strong>第 3 格</strong>：标签君演示快排一次 partition：数组 <code>[3,7,1,8,2,6]</code>，pivot 选 6，双指针从两端扫描交换，pivot 归位后左右递归。</li><li><strong>第 4 格</strong>：码叔结案——V8 的 <code>sort</code> 是 TimSort（短数组插入、长数组归并），业务别手写，并给出三大坑点。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-sort-的字典序陷阱" tabindex="-1">第 1 格 · sort 的字典序陷阱 <a class="header-anchor" href="#第-1-格-·-sort-的字典序陷阱" aria-label="Permalink to &quot;第 1 格 · sort 的字典序陷阱&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → [1, 10, 9]</span></span></code></pre></div><ul><li><code>Array.prototype.sort()</code> 不传比较器时，会把元素<strong>转成字符串</strong>再按 UTF-16 码元比较；</li><li><code>&quot;10&quot; &lt; &quot;9&quot;</code> 因为 <code>&quot;1&quot; &lt; &quot;9&quot;</code>，导致 10 排在 9 前面；</li><li>修复：<code>arr.sort((a, b) =&gt; a - b)</code>，比较器返回负数/零/正数决定顺序。</li></ul><h3 id="第-2-格-·-六路选手" tabindex="-1">第 2 格 · 六路选手 <a class="header-anchor" href="#第-2-格-·-六路选手" aria-label="Permalink to &quot;第 2 格 · 六路选手&quot;">​</a></h3><table tabindex="0"><thead><tr><th>家族</th><th>算法</th><th>平均复杂度</th><th>特点</th></tr></thead><tbody><tr><td>O(n²)</td><td>冒泡、选择、插入</td><td>n²</td><td>实现简单；插入在近乎有序时接近 O(n)</td></tr><tr><td>O(n log n)</td><td>归并、快排、堆排</td><td>n log n</td><td>大数据主力；归并稳定，快排原地，堆排不占栈</td></tr></tbody></table><ul><li>归并：分治 + 合并，稳定但需要 <code>O(n)</code> 辅助空间；</li><li>快排：分区 + 递归，原地不稳定，平均最快；</li><li>堆排：建堆 + 逐个取顶，原地不稳定，最坏也 <code>O(n log n)</code>。</li></ul><h3 id="第-3-格-·-快排-partition-走查" tabindex="-1">第 3 格 · 快排 partition 走查 <a class="header-anchor" href="#第-3-格-·-快排-partition-走查" aria-label="Permalink to &quot;第 3 格 · 快排 partition 走查&quot;">​</a></h3><p>数组 <code>[3,7,1,8,2,6]</code>，选末尾 6 为 pivot：</p><ol><li><code>j</code> 从左扫到右，遇到比 6 小的就换到 <code>i</code> 区域；</li><li><code>1</code>、<code>2</code> 依次被换到左侧；</li><li>扫描结束后把 pivot 与 <code>i+1</code> 位置交换；</li><li>结果 <code>[3,1,2 | 6 | 7,8]</code>，pivot 归位，左右子数组递归同样处理。</li></ol><h3 id="第-4-格-·-v8-的-timsort" tabindex="-1">第 4 格 · V8 的 TimSort <a class="header-anchor" href="#第-4-格-·-v8-的-timsort" aria-label="Permalink to &quot;第 4 格 · V8 的 TimSort&quot;">​</a></h3><ul><li><strong>短数组（≤22）</strong>：直接插入排序；</li><li><strong>长数组</strong>：先跑插入整理出有序 run，再用归并合并；</li><li>业务代码<strong>不要手写排序</strong>，<code>sort</code> 已针对各种分布做过优化，且是稳定排序。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../22-frontend-data-structures#_22-11-本章避坑清单">《22.11 本章避坑清单》</a></p></blockquote><ol><li><strong>数字排序不传比较器</strong>：字典序导致 <code>10</code> 排在 <code>9</code> 前面，必须写 <code>(a, b) =&gt; a - b</code>；</li><li><strong>把 sort 当成纯函数</strong>：<code>sort()</code> 会<strong>原地修改</strong>原数组，需要保留原数组时先 <code>slice()</code> 或 <code>[...arr]</code> 再排；</li><li><strong>稳定性选错算法</strong>：需要稳定排序（如同分保持原顺序）时不能用快排/堆排，应选归并或直接用原生 <code>sort</code>；</li><li><strong>对象数组比较器写错</strong>：<code>sort((a, b) =&gt; a.score - b.score)</code>，别写成 <code>a - b</code> 导致 NaN。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li><strong>为什么 <code>[10,9,1].sort()</code> 结果是 <code>[1,10,9]</code>？</strong>——默认按字符串字典序比较，<code>&quot;10&quot;</code> 的首字符 <code>&quot;1&quot;</code> 小于 <code>&quot;9&quot;</code>；必须传 <code>(a,b) =&gt; a-b</code> 数字比较器。</li><li><strong>快排和归并排序的核心区别是什么？</strong>——快排原地、不稳定、平均 <code>O(n log n)</code>；归并稳定、需要 <code>O(n)</code> 辅助空间，最坏情况也是 <code>O(n log n)</code>。</li><li><strong>V8 的 <code>Array.prototype.sort</code> 用的是什么算法？</strong>——TimSort：短数组（≤22 个元素）用插入排序，长数组拆成有序 run 后用归并排序合并，且稳定。</li></ol>',21)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
